SOURCE_FIELDS={'year','state','closed_sha256','previous_sha256','result_account','issues','accounts','opening','entries','calculation','asset_schedule'}

def require(ok,message='Ergebnisverwendung: ursprüngliche Buchung, Beschluss, Gegenkonto und Jahresergebnis vollständig abstimmen.'):
 if not ok:raise ValueError(message)

def validate_rule(rule):
 if 'tax_equalization_contract' in rule:
  from ebilanz_tax_equalization import validate_rule as equalization_rule
  equalization_rule(rule);return
 ref=rule.get('income_use_contract')
 if ref is None:
  require(rule.get('group')!='result_use');return
 code=ref.removesuffix('@1');require(ref==code+'@1' and code in CONTRACTS);c=CONTRACTS[code]
 require(rule.get('group')=='result_use' and rule.get('condition')=='detail_choice' and rule.get('target')==c['targets'][0] and rule.get('allowed_targets')==c['targets'] and not rule.get('disclosures'))
 if 'codes' in rule:require(rule['codes']==[code])

def check_values(values,mapping,*,book_only=False):
 from ebilanz_mapping import checked_source
 from ebilanz_club_scope import calculate,lines,amount
 root=Path(__file__).resolve().parent.parent;year=values['year'];side='book' if book_only else 'tax';selected={k:a for k,a in values[side]['accounts'].items() if a['group']=='result_use' and a['skr_code']!='77690'}
 if not selected:return {'keys':set(),'active':False,'facts':{},'balance_effect':0,'family':None}
 require('period' not in values,'Ergebnisverwendung benötigt hier den qualifizierten Kalenderjahresabschluss; andere Abschlusszeiträume separat abstimmen.')
 evidence=values.get('income_use_source');require(isinstance(evidence,dict) and set(evidence)=={'schema','source'} and type(evidence['schema']) is int and evidence['schema']==1)
 source=evidence['source'];require(isinstance(source,dict) and set(source)==SOURCE_FIELDS and source['year']==year and source['state']=='closed' and source['issues']==[] and source['closed_sha256']==values['journal_sha256'])
 require(calculate(year,source['accounts'],source['opening'],source['entries'])==source['calculation']==values['book'])
 _,rules,_=checked_source(year,(root/'resources/ebilanz/skr42-6.9.json').read_bytes().replace(b'\r\n',b'\n'),(root/f'data/skr42-{year}.json').read_bytes().replace(b'\r\n',b'\n'))
 facts={};families=set();effect=0
 for key,row in selected.items():
  code=row['skr_code'];require(code in CONTRACTS and key in mapping and rules[code].get('income_use_contract')==code+'@1');validate_rule(rules[code]);c=CONTRACTS[code];target=mapping[key];require(target in c['targets'])
  for side in ('book','tax'):
   other=values[side]['accounts'][key];require(other['opening_cents']==0 and other['skr_code']==code and other['group']=='result_use')
  effect=amount(effect+row['amount_cents']);family='foundation' if target.startswith('incomeUse.resultFoundations.') else 'corporate';families.add(family)
  sign=(1 if target=='incomeUse.resultFoundations.prevYear' else -1 if target in ('incomeUse.resultFoundations.transferWithdrawalRevenueReserves','incomeUse.resultFoundations.transferWithdrawalReallocation','incomeUse.resultFoundations.increaseDecreaseStatutoryBoundCapital') else c['orientation'])
  facts[target]=amount(facts.get(target,0)+sign*row['amount_cents'])
 # Exact original contra account is checked per voucher, including reversals.
 for entries in (source['entries'],values['current_adjustments']):
  for entry in entries:
   use=[l for l in entry['lines'] if l['account'] in selected]
   if not use:continue
   require(len(use)==1 and len(entry['lines'])==2)
   line=use[0];c=CONTRACTS[selected[line['account']]['skr_code']];peer=next(l for l in entry['lines'] if l['account']!=line['account']);account=values['tax']['accounts'][peer['account']];rule=rules.get(account['skr_code'],{})
   possible=rule.get('allowed_targets',[rule.get('target')]);confirmed=mapping.get(peer['account']) or (rule.get('target') if not rule.get('condition') else None)
   require(confirmed in possible and confirmed in c['counter_targets'])
   require((line['debit_cents']==peer['credit_cents'] and line['credit_cents']==peer['debit_cents']))
 require(len(families)==1,'Ergebnisverwendung für Verein/Stiftung oder Kapitalgesellschaft einheitlich bestätigen.')
 # Reviewed tax adjustments are replayed from the source, not accepted from net balances.
 opening={k:a['opening_cents'] for k,a in values['book']['accounts'].items()};entries=deepcopy(source['entries'])
 for phase in ('opening_adjustments','current_adjustments'):
  for i,entry in enumerate(values[phase]):
   lines(entry['lines'],source['accounts'],phase=='opening_adjustments')
   if phase=='opening_adjustments':
    for l in entry['lines']:opening[l['account']]=amount(opening[l['account']]+l['debit_cents']-l['credit_cents'])
   else:entries.append({'id':hashlib.md5(('income-use-tax-'+str(i)+entry['id']).encode()).hexdigest(),'date':str(year)+'-12-31','lines':entry['lines']})
 original=[{'account':k,'debit_cents':max(0,n),'credit_cents':max(0,-n),'sphere':''} for k,n in sorted(opening.items()) if n]
 require(calculate(year,source['accounts'],original,entries)==values['tax'])
 active=any(a['amount_cents'] for a in selected.values());family=next(iter(families))
 if active:
  # Existing carry before use must be completely transferred into the declared result.
  require(all(a['amount_cents']==0 for a in values[side]['accounts'].values() if a['skr_code'] in ('29700','29780')),'Vortrag vor Verwendung vollständig in den bestätigten Ergebnisvortrag nach Verwendung umbuchen.')
  result=amount(values[side]['annual_result_cents']+effect)
  if family=='foundation':facts.update({'incomeUse.resultFoundations.currentYear':values[side]['annual_result_cents'],'incomeUse.resultFoundations':result})
  else:facts.update({'incomeUse.gainLoss.netIncome':values[side]['annual_result_cents'],'incomeUse.gainLoss':result})
 else:facts={}
 return {'keys':set(selected),'active':active,'facts':facts,'balance_effect':effect,'family':family}

NETWORK_SHA256='43ebaa97cbbda4e4b3fc471e3465840087af7b922f1d497c9c97c1af9c663465'

def network():
 raw=(Path(__file__).resolve().parent.parent/'resources/ebilanz/income-use-network.json').read_bytes().replace(b'\r\n',b'\n')
 require(hashlib.sha256(raw).hexdigest()==NETWORK_SHA256,'Amtliche Ergebnisverwendungs-Taxonomie geändert; erneut qualifizieren.')
 return json.loads(raw)
